// Live values — what each control wrote to nb, and its JavaScript type.
// (On a fresh Run All the controls seed their defaults, so this is populated
//  even before you touch anything.)
const show = (key) => {
  const v = nb.get(key);
  return { value: v, type: typeof v };
};

return {
  name:   show('name'),
  age:    show('age'),     // a real number, not "36"
  colour: show('colour'),
  day:    show('day'),
  note:   show('note'),
};

// Gotcha: the number control CLAMPS to [min, max] and coerces to a number.
// Try typing 999 in the Age field above — it commits as 120, not 999.
const age = nb.get('age');
console.log('age is a', typeof age, '=', age);
console.log('in range 0..120:', age >= 0 && age <= 120);

// And a string that looks numeric stays a string when it comes from a text box:
const name = nb.get('name');
console.log('name stays a string even if you type digits:', typeof name);

return age <= 120 && typeof name === 'string'
  ? 'clamped + typed correctly ✓'
  : 'unexpected — did you change the control types?';
